from __future__ import annotations
import contextlib
import io
import json
import sys
from types import ModuleType

SOURCE = '#!/usr/bin/env python3\n"""测量不确定度评定（GUM 合成 + 扩展）。\n\n给不出不确定度的测量结论不可交付；本脚本把 A 类/B 类分量按要求合成并给出 U(k)。\n只用标准库。输出 JSON（统一信封 status="ok"/"error"）。\n\nB 类分量写法： --b "名称:参数1:类型[:参数2][:灵敏度系数]"\n  类型与参数含义（参数1/参数2 按类型解释）：\n    std          参数1 = 标准不确定度 u（证书直接给 u 时用）\n    expanded     参数1 = 扩展不确定度 U，参数2 = 包含因子 k\n    rect         参数1 = 半宽 a（均匀分布）        -> u = a/sqrt(3)\n    tri          参数1 = 半宽 a（三角分布）        -> u = a/sqrt(6)\n    mpe          参数1 = 最大允许误差 ±a（按均匀）  -> u = a/sqrt(3)\n    resolution   参数1 = 分辨力 delta（均匀）       -> u = delta/(2*sqrt(3))\n  灵敏度系数默认为 1；对同一被测量为非线性关系时显式给 c_i = df/dx_i。\n\n示例：\n  python uncertainty.py --a 10.02,10.05,9.98,10.01,10.03 \\\n      --b "标准器:0.05:expanded:2" --b "分辨力:0.01:resolution" \\\n      --b "温漂:0.2:mpe:1:0.5" --result 10.018 --unit kPa\n"""\nimport argparse\nimport json\nimport math\nimport statistics\nimport sys\n\nSUPPORTED = {"std", "expanded", "rect", "tri", "mpe", "resolution"}\n# 每种类型允许的字段数（含名称）：{类型: (最少, 最多)}\nFIELD_COUNTS = {\n    "std": (3, 4), "rect": (3, 4), "tri": (3, 4),\n    "mpe": (3, 4), "resolution": (3, 4), "expanded": (4, 5),\n}\n\n\ndef parse_component(spec):\n    parts = spec.split(":")\n    if len(parts) < 3:\n        raise ValueError(f"--b 分量格式错误：{spec!r}，至少需要 名称:参数1:类型")\n    name = parts[0].strip()\n    if not name:\n        raise ValueError(f"--b 分量缺少名称：{spec!r}")\n    kind = parts[2].strip().lower()\n    if kind not in SUPPORTED:\n        raise ValueError(f"未知类型 {kind!r}，支持 {sorted(SUPPORTED)}")\n    lo, hi = FIELD_COUNTS[kind]\n    if not (lo <= len(parts) <= hi):\n        raise ValueError(\n            f"--b 分量的字段数不对：{spec!r} 有 {len(parts)} 段，"\n            f"类型 {kind} 只接受 名称:参数1:{kind}"\n            + (":参数2(k):灵敏度系数" if kind == "expanded" else ":灵敏度系数")\n            + " —— 拒绝静默忽略多余字段"\n        )\n    try:\n        p1 = float(parts[1])\n    except ValueError:\n        raise ValueError(f"--b 分量的参数1 不是数字：{spec!r}")\n    p2 = None\n    ci = 1.0\n    if kind == "expanded":\n        p2 = float(parts[3])\n        if p2 <= 0:\n            raise ValueError(f"包含因子 k 必须为正：{spec!r}")\n        if len(parts) == 5:\n            ci = float(parts[4])\n    elif len(parts) == 4:\n        ci = float(parts[3])\n\n    if kind in ("rect", "tri", "mpe", "resolution") and p1 < 0:\n        raise ValueError(f"半宽/误差/分辨力不应为负：{spec!r}")\n\n    if kind == "std":\n        u = abs(p1)\n        source = "直接给定标准不确定度"\n    elif kind == "expanded":\n        u = abs(p1) / p2\n        source = f"U={p1:g} / k={p2:g}"\n    elif kind == "rect":\n        u = p1 / math.sqrt(3)\n        source = f"半宽 {p1:g}，均匀分布 / sqrt(3)"\n    elif kind == "tri":\n        u = p1 / math.sqrt(6)\n        source = f"半宽 {p1:g}，三角分布 / sqrt(6)"\n    elif kind == "mpe":\n        u = p1 / math.sqrt(3)\n        source = f"MPE ±{p1:g}，按均匀分布 / sqrt(3)"\n    else:  # resolution\n        u = p1 / (2 * math.sqrt(3))\n        source = f"分辨力 {p1:g}，均匀分布 / (2*sqrt(3))"\n\n    return {"name": name, "kind": kind, "raw": p1, "raw2": p2, "ci": ci,\n            "u": u, "contribution": abs(ci) * u, "source": source,\n            "dof": math.inf if kind != "std" else None,\n            "dof_basis": "B 类按自由度无穷处理" if kind != "std" else "由样本数决定"}\n\n\ndef t_factor(confidence, dof):\n    """t 分布分位数近似（Student-t，用于自由度有限时的扩展不确定度）。"""\n    # 常用置信度下的近似系数表（按自由度插值），覆盖 nu=1..30 与无穷\n    table = {\n        0.95: {1: 12.71, 2: 4.30, 3: 3.18, 4: 2.78, 5: 2.57, 6: 2.45, 7: 2.36, 8: 2.31,\n               9: 2.26, 10: 2.23, 12: 2.18, 15: 2.13, 20: 2.09, 25: 2.06, 30: 2.04, 50: 2.01},\n        0.99: {1: 63.66, 2: 9.92, 3: 5.84, 4: 4.60, 5: 4.03, 6: 3.71, 7: 3.50, 8: 3.36,\n               9: 3.25, 10: 3.17, 12: 3.05, 15: 2.95, 20: 2.85, 25: 2.79, 30: 2.75, 50: 2.68},\n    }\n    if confidence not in table:\n        return 2.0\n    tab = table[confidence]\n    if dof == math.inf or dof > 50:\n        return 1.96 if confidence == 0.95 else 2.576\n    keys = sorted(tab)\n    if dof <= keys[0]:\n        return tab[keys[0]]\n    for lo, hi in zip(keys, keys[1:]):\n        if lo <= dof <= hi:\n            frac = (dof - lo) / (hi - lo)\n            return tab[lo] + frac * (tab[hi] - tab[lo])\n    return tab[keys[-1]]\n\n\ndef main():\n    p = argparse.ArgumentParser(description="GUM 不确定度评定")\n    p.add_argument("--a", default=None, help="A 类：逗号分隔的重复测量样本")\n    p.add_argument("--a-name", default="A类重复测量", help="A 类分量名称")\n    p.add_argument("--a-ci", type=float, default=1.0, help="A 类灵敏度系数")\n    p.add_argument("--b", action="append", default=[], help="B 类分量，可重复")\n    p.add_argument("--k", type=float, default=2.0, help="扩展不确定度包含因子（默认 2）")\n    p.add_argument("--confidence", type=float, default=None,\n                   help="给定置信度(0.95/0.99)时按 t 分布自由度修正 k")\n    p.add_argument("--result", type=float, default=None, help="被测量最佳估计值，用于格式化输出")\n    p.add_argument("--unit", default="", help="单位")\n    args = p.parse_args()\n\n    out = {"status": "error"}\n    comps = []\n\n    if args.a:\n        try:\n            samples = [float(s) for s in args.a.replace(";", ",").split(",") if s.strip() != ""]\n        except ValueError:\n            out["error"] = f"--a 含非数字项：{args.a!r}"\n            print(json.dumps(out, ensure_ascii=False, indent=2))\n            return 1\n        if len(samples) < 2:\n            out["error"] = f"A 类至少需要 2 个样本（当前 {len(samples)}）"\n            print(json.dumps(out, ensure_ascii=False, indent=2))\n            return 1\n        mean = statistics.fmean(samples)\n        s = statistics.stdev(samples)\n        n = len(samples)\n        u_a = s / math.sqrt(n)\n        comps.append({\n            "name": args.a_name, "kind": "A", "n": n, "mean": mean, "std": s,\n            "ci": args.a_ci, "u": u_a, "contribution": abs(args.a_ci) * u_a,\n            "source": f"s={s:.6g}, n={n}, u=s/sqrt(n)", "dof": n - 1,\n        })\n        out["type_a_statistics"] = {"n": n, "mean": mean, "std": s, "u_a": u_a}\n\n    for spec in args.b:\n        try:\n            comps.append(parse_component(spec))\n        except ValueError as e:\n            out["error"] = str(e)\n            print(json.dumps(out, ensure_ascii=False, indent=2))\n            return 1\n\n    if not comps:\n        out["error"] = "没有任何分量：至少给 --a 或一个 --b。没有分量就无法评定不确定度。"\n        print(json.dumps(out, ensure_ascii=False, indent=2))\n        return 1\n\n    for c in comps:\n        if c["dof"] is None or c["dof"] == math.inf:\n            c["dof_infinite"] = True\n        else:\n            c["dof_infinite"] = False\n        if c["dof"] is None:\n            c["dof"] = math.inf\n\n    u_c = math.sqrt(sum(c["contribution"] ** 2 for c in comps))\n    if u_c == 0:\n        out["error"] = "合成不确定度为 0：所有分量都是 0 或未给，无法给出 U（不要报 0）"\n        out["components"] = comps\n        print(json.dumps(out, ensure_ascii=False, indent=2))\n        return 1\n\n    # 相关项提醒：GUM 要求协方差项，脚本只在无相关假设下合成\n    warnings = []\n    names = [c["name"] for c in comps]\n    if len(names) != len(set(names)):\n        warnings.append("存在重名分量，合成时按独立处理；若实际相关请手工引入协方差项")\n    warnings.append("本脚本按各分量相互独立合成；同一标准器标定的多个量之间存在正相关，"\n                    "忽略相关项会低估 u_c，需手工加入 2*sum(c_i*c_j*r_ij*u_i*u_j)")\n\n    # Welch-Satterthwaite 有效自由度\n    denom = sum((c["contribution"] ** 4) / c["dof"] for c in comps if c["dof"] != math.inf)\n    nu_eff = math.inf if denom == 0 else u_c ** 4 / denom\n\n    k = args.k\n    k_source = f"指定 k={k:g}"\n    if args.confidence is not None:\n        if nu_eff == math.inf:\n            k = t_factor(args.confidence, math.inf)\n            k_source = f"自由度无穷，按正态分位数（置信度 {args.confidence:g}）"\n        else:\n            k = t_factor(args.confidence, nu_eff)\n            k_source = f"按 Welch-Satterthwaite 有效自由度 {nu_eff:.1f} 取 t 分位数（置信度 {args.confidence:g}）"\n    U = k * u_c\n\n    # JSON 严格模式不允许 Infinity：对外只给 null + 布尔标记\n    for c in comps:\n        if c["dof"] == math.inf:\n            c["dof"] = None\n\n    out.update({\n        "components": comps,\n        "u_combined": u_c,\n        "effective_dof": None if nu_eff == math.inf else nu_eff,\n        "effective_dof_infinite": nu_eff == math.inf,\n        "k": k,\n        "k_source": k_source,\n        "U_expanded": U,\n        "warnings": warnings,\n        "dominant_components": [c["name"] for c in\n                                sorted(comps, key=lambda x: -x["contribution"])[:3]],\n    })\n\n    if args.result is not None:\n        out["result_string"] = f"{args.result:g} ± {U:.4g} {args.unit}".strip()\n        out["result_statement"] = (\n            f"测量结果 {args.result:g} {args.unit}，扩展不确定度 U = {U:.4g} {args.unit}，"\n            f"（{k_source}，约 {int(round((args.confidence or 0.95) * 100))}% 置信）"\n        )\n    out["status"] = "ok"\n\n    print(json.dumps(out, ensure_ascii=False, indent=2))\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'

def main():
    capture, errors = io.StringIO(), io.StringIO()
    code = 0
    try:
        request = json.load(sys.stdin)
        args = request.get('args')
        if not isinstance(args, list) or any(not isinstance(x, str) for x in args):
            raise ValueError('args_must_be_string_list')
        sys.argv = ['uncertainty.py'] + args
        module = ModuleType('__main__')
        module.__file__ = 'uncertainty.py'
        sys.modules['__main__'] = module
        with contextlib.redirect_stdout(capture), contextlib.redirect_stderr(errors):
            exec(compile(SOURCE, 'uncertainty.py', 'exec'), module.__dict__)
    except SystemExit as error:
        code = error.code if isinstance(error.code, int) else 1
    except Exception as error:
        code = 1
        errors.write(type(error).__name__ + ': ' + str(error))
    print(json.dumps({'exit_code': code, 'stdout': capture.getvalue(), 'stderr': errors.getvalue()}, ensure_ascii=False))
    return code

if __name__ == '__main__':
    raise SystemExit(main())
